/**
 * Crypto compatibility test — verifies Deno WebCrypto AES-256-CBC
 * produces output that Node.js crypto can decrypt and vice-versa.
 *
 * Run with: deno test --allow-env supabase/functions/_shared/crypto_test.ts
 *
 * Set ENCRYPTION_KEY env var to the same 32+ char key used by Node.
 */
import { encryptPassword, decryptPassword } from "./crypto.ts";
import { assertEquals, assertNotEquals } from "@std/assert";

// Known test vector — generated by Node.js crypto.js with:
//   ENCRYPTION_KEY = "0123456789abcdef0123456789abcdef" (32 chars)
//   plaintext = "testPassword123!"
// The IV is random so we can't hardcode the full output, but we
// can verify round-trip and cross-decrypt a Node-encrypted value.
const NODE_ENCRYPTED = "5XlOhAU13a+h6e3xVExuZw==:fhWxiP3b0hNkE/9Q5G1X1CtA9H3VFxVWNt2w6Jr5jyw=";

Deno.test("crypto round-trip: encrypt → decrypt returns original", async () => {
  const plaintext = "MySecretPassword#2024";
  const encrypted = await encryptPassword(plaintext);
  const decrypted = await decryptPassword(encrypted);
  assertEquals(decrypted, plaintext);
});

Deno.test("crypto format: output is base64iv:base64cipher", async () => {
  const encrypted = await encryptPassword("test");
  const parts = encrypted.split(":");
  assertEquals(parts.length, 2);
  // IV should decode to 16 bytes
  const ivBytes = atob(parts[0]);
  assertEquals(ivBytes.length, 16);
});

Deno.test("crypto uniqueness: same plaintext produces different ciphertext", async () => {
  const a = await encryptPassword("same");
  const b = await encryptPassword("same");
  assertNotEquals(a, b);
});

Deno.test("crypto cross-platform: decrypt Node-encrypted value", async (t) => {
  if (!NODE_ENCRYPTED) {
    t.step.skip("NODE_ENCRYPTED not set — run generate_vector.js first");
    return;
  }
  const decrypted = await decryptPassword(NODE_ENCRYPTED);
  assertEquals(decrypted, "testPassword123!");
});

Deno.test("crypto error: invalid format throws", async () => {
  try {
    await decryptPassword("invalid");
    // Should have thrown
    assertEquals(true, false, "Expected error was not thrown");
  } catch (e) {
    assertEquals((e as Error).message, "Invalid encrypted password format");
  }
});
